<script setup lang="ts">
import { computed, nextTick, reactive, ref, watch } from 'vue';
import type { MatchdaySummary, TeamSummary, TournamentSummary, TournamentVenue } from '@torneos/shared';
import Icon from './Icon.vue';

const props=defineProps<{tournament:TournamentSummary;categories:TournamentSummary[];entries:TeamSummary[];days:MatchdaySummary[];dayId:string;focusMatchId?:string;venues:TournamentVenue[];officialMatchIds:string[];organizationId:string;csrfToken:string}>();
const emit=defineEmits<{refresh:[]}>();
const day=computed(()=>props.days.find(item=>item.id===props.dayId));
const categories=computed(()=>props.categories.filter(item=>item.edition_id===(day.value?.edition_id||props.categories[0]?.edition_id)));
const mode=ref<'new'|'teams'|'schedule'|''>('');
const activeMatch=ref<MatchdaySummary['matches'][number]|null>(null);
const busy=ref(false),error=ref(''),message=ref('');
const removeMatchId=ref(''),removeDayOpen=ref(false);
const lastScheduled=ref<{date:string;time:string;venueId:string;courtLabel:string;durationMinutes:number}|null>(null);
const form=reactive({categoryId:'',homeEntryId:'',awayEntryId:'',venueId:'',courtLabel:'',date:new Date().toISOString().slice(0,10),time:'18:00',durationMinutes:60});
const editForm=ref<HTMLFormElement|null>(null);
let focusedMatchId='';
watch(()=>props.dayId,()=>{mode.value='';activeMatch.value=null;lastScheduled.value=null;error.value='';message.value='';});
function teams(){return props.entries.filter(item=>item.category_id===form.categoryId&&item.status==='active');}
function beginNew(){mode.value='new';activeMatch.value=null;form.categoryId=categories.value[0]?.category_id||'';form.homeEntryId='';form.awayEntryId='';form.venueId=props.venues[0]?.id||'';form.courtLabel='';form.date=day.value?.matches.at(-1)?.match_date||new Date().toISOString().slice(0,10);form.time='18:00';form.durationMinutes=60;error.value='';}
function beginEdit(match:MatchdaySummary['matches'][number],selected:'teams'|'schedule'){activeMatch.value=match;mode.value=selected;form.categoryId=match.category_id;form.homeEntryId=match.home_entry_id;form.awayEntryId=match.away_entry_id;form.venueId=match.venue_id||props.venues[0]?.id||'';form.courtLabel=match.court_label==='Cancha 1'?'':match.court_label||'';form.date=match.match_date||new Date().toISOString().slice(0,10);form.time=match.match_time||'18:00';form.durationMinutes=match.duration_minutes||60;error.value='';}
watch([()=>props.focusMatchId,day],async([matchId,current])=>{if(!matchId||!current||focusedMatchId===matchId)return;const match=current.matches.find(item=>item.id===matchId);if(!match||props.officialMatchIds.includes(matchId))return;focusedMatchId=matchId;beginEdit(match,'teams');await nextTick();editForm.value?.scrollIntoView({behavior:'smooth',block:'start'});},{immediate:true});
async function send(path:string,method:string,body:object={}){const response=await fetch(`/api/v1/organizations/${props.organizationId}${path}`,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':props.csrfToken},...(method==='GET'?{}:{body:JSON.stringify(body)})});const data=await response.json();if(!response.ok)throw new Error(data.message||'No se pudo guardar.');return data;}
async function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await action();}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo guardar.';}finally{busy.value=false;}}
async function createDay(){await run(async()=>{const result=await send(`/editions/${props.categories[0].edition_id}/matchdays`,'POST',{ordinal:Math.max(0,...props.days.filter(item=>item.edition_id===props.categories[0].edition_id).map(item=>item.ordinal))+1});emit('refresh');location.hash=`#/torneo/${props.tournament.id}/fixture/${result.id}`;});}
async function save(){if(!day.value||!form.homeEntryId||!form.awayEntryId||form.homeEntryId===form.awayEntryId)return;await run(async()=>{
  if(mode.value==='new')await send(`/matchdays/${day.value!.id}/matches`,'POST',{categoryId:form.categoryId,homeEntryId:form.homeEntryId,awayEntryId:form.awayEntryId,venueId:form.venueId,courtLabel:form.courtLabel.trim()||'Cancha 1',date:form.date,time:form.time,durationMinutes:Number(form.durationMinutes),refereeName:null});
  if(mode.value==='teams'&&activeMatch.value)await send(`/fixture/matches/${activeMatch.value.id}/participants`,'PATCH',{homeEntryId:form.homeEntryId,awayEntryId:form.awayEntryId,reason:'Corrección de equipos por el organizador'});
  if(mode.value==='schedule'&&activeMatch.value)await send(`/fixture/matches/${activeMatch.value.id}/schedule`,'PATCH',{matchdayId:day.value!.id,venueId:form.venueId,courtLabel:form.courtLabel.trim()||'Cancha 1',date:form.date,time:form.time,durationMinutes:Number(form.durationMinutes),refereeName:null,expectedRevision:activeMatch.value.schedule_revision,reason:'Reprogramación por el organizador'});
  if(mode.value==='schedule')lastScheduled.value={date:form.date,time:form.time,venueId:form.venueId,courtLabel:form.courtLabel.trim()||'Cancha 1',durationMinutes:Number(form.durationMinutes)};
  mode.value='';activeMatch.value=null;message.value='Guardado.';emit('refresh');
});}
async function scheduleRemaining(style:'same'|'sequential'){if(!day.value||!lastScheduled.value)return;await run(async()=>{const pending=day.value!.matches.filter(match=>!match.match_time);const base=lastScheduled.value!;const matches=pending.map((match,index)=>{const clock=new Date(`${base.date}T${base.time}:00Z`);if(style==='sequential')clock.setUTCMinutes(clock.getUTCMinutes()+(index+1)*base.durationMinutes);return {matchId:match.id,schedule:{matchdayId:day.value!.id,venueId:base.venueId,courtLabel:style==='same'?`Cancha ${index+2}`:base.courtLabel,date:clock.toISOString().slice(0,10),time:clock.toISOString().slice(11,16),durationMinutes:base.durationMinutes,refereeName:null,expectedRevision:match.schedule_revision,reason:'Programación de la Fecha por el organizador'}};});await send(`/matchdays/${day.value!.id}/schedule-batch`,'POST',{matches});lastScheduled.value=null;message.value='Partidos programados.';emit('refresh');});}
async function publishDay(){if(!day.value)return;await run(async()=>{const preview=await send(`/matchdays/${day.value!.id}/preview`,'GET',{});if(preview.missing?.length)throw new Error(preview.missing.join(' '));await send(`/matchdays/${day.value!.id}/publish`,'POST',{expectedRevision:preview.revision,reason:'Fecha confirmada por el organizador'});message.value='Fecha publicada.';emit('refresh');});}
async function archiveMatch(matchId:string){await run(async()=>{await send(`/fixture/matches/${matchId}/archive`,'POST');removeMatchId.value='';message.value='Partido retirado. Podés recuperarlo abajo.';emit('refresh');});}
async function restoreMatch(matchId:string){await run(async()=>{await send(`/fixture/matches/${matchId}/restore`,'POST');message.value='Partido recuperado.';emit('refresh');});}
async function archiveDay(){if(!day.value)return;await run(async()=>{await send(`/matchdays/${day.value!.id}/archive`,'POST');location.hash=`#/torneo/${props.tournament.id}/fixture`;emit('refresh');});}
</script>

<template>
  <div class="form-page stack">
    <a :href="`#/torneo/${tournament.id}/fixture`" class="back"><Icon name="back" />Fixture</a>
    <div v-if="dayId==='new'" class="stack"><h1>Nueva fecha</h1><button type="button" class="btn primary full" :disabled="busy" @click="createDay">Crear Fecha {{ Math.max(0,...days.map(item=>item.ordinal))+1 }}</button></div>
    <template v-else-if="day">
      <div class="between"><h1>Fecha {{ day.ordinal }}</h1><span class="badge" :class="day.status==='published'?'active':'pending'">{{ day.status==='published'?'Publicada':'Borrador' }}</span></div>
      <div class="action-grid"><a class="btn" :href="`#/torneo/${tournament.id}/partidos/${day.id}`">Ver partidos</a><a v-if="day.status==='published'" class="btn" :href="`#/flyers/${tournament.id}/matchday/${day.id}`">Flyer de la fecha</a><button v-if="day.status==='draft'" type="button" class="btn primary" @click="beginNew">Agregar partido</button></div>
      <div v-for="match in day.matches" :key="match.id" class="workspace-line"><Icon name="ball" /><span><strong>{{ match.home_name }} vs {{ match.away_name }}</strong><small>{{ match.match_date&&match.match_time?`${match.match_date} · ${match.match_time}`:'Sin horario' }}</small></span><div class="workspace-actions"><a v-if="officialMatchIds.includes(match.id)" class="btn" :href="`#/partido/${match.category_id}/${match.id}`">Ver acta</a><template v-else><button type="button" class="btn" @click="beginEdit(match,'teams')">Equipos</button><button type="button" class="btn" @click="beginEdit(match,'schedule')">{{ match.match_time?'Horario':'Programar' }}</button><button v-if="day.status==='draft'&&!match.fixture_phase_id" type="button" class="btn" @click="removeMatchId=match.id">Quitar</button></template></div><div v-if="removeMatchId===match.id" class="inline-confirm"><span>¿Retirar este partido?</span><button type="button" class="btn" @click="removeMatchId=''">Volver</button><button type="button" class="btn danger" :disabled="busy" @click="archiveMatch(match.id)">Retirar</button></div></div>
      <div v-if="lastScheduled&&day.matches.some(match=>!match.match_time)" class="fixture-edit stack"><h3>Resto de la fecha</h3><div class="choices"><button type="button" class="choice" :disabled="busy" @click="scheduleRemaining('same')">Mismo día y hora</button><button type="button" class="choice" :disabled="busy" @click="scheduleRemaining('sequential')">Uno tras otro</button><button type="button" class="choice" @click="lastScheduled=null">Por separado</button></div></div>
      <div v-if="!day.matches.length" class="empty-list">Fecha sin partidos.</div>
      <div v-if="day.archivedMatches?.length" class="fixture-removed"><span>Retirados</span><button v-for="match in day.archivedMatches" :key="match.id" type="button" class="text-action" :disabled="busy" @click="restoreMatch(match.id)">Recuperar {{ match.home_name }} vs {{ match.away_name }}</button></div>
      <div v-if="day.status==='draft'&&!day.matches.length" class="fixture-remove-day"><button v-if="!removeDayOpen" type="button" class="text-action" @click="removeDayOpen=true">Quitar fecha</button><div v-else class="inline-confirm"><span>¿Retirar Fecha {{ day.ordinal }}?</span><button type="button" class="btn" @click="removeDayOpen=false">Volver</button><button type="button" class="btn danger" :disabled="busy" @click="archiveDay">Retirar</button></div></div>
      <button v-if="day.status==='draft'&&day.matches.length" type="button" class="btn full" :disabled="busy" @click="publishDay">Publicar fecha</button>
      <form v-if="mode" ref="editForm" class="stack fixture-edit" @submit.prevent="save">
        <div class="between"><h2>{{ mode==='new'?'Agregar partido':mode==='teams'?'Cambiar equipos':'Reprogramar' }}</h2><button type="button" class="btn" @click="mode=''">Cerrar</button></div>
        <div v-if="mode==='new'&&categories.length>1"><span class="label">Categoría</span><div class="choices grid"><button v-for="category in categories" :key="category.category_id" type="button" class="choice" :aria-pressed="form.categoryId===category.category_id" @click="form.categoryId=category.category_id;form.homeEntryId='';form.awayEntryId=''">{{ category.category_name }}</button></div></div>
        <template v-if="mode!=='schedule'"><div><span class="label">Local</span><div class="choices grid"><button v-for="team in teams()" :key="team.entry_id" type="button" class="choice" :aria-pressed="form.homeEntryId===team.entry_id" @click="form.homeEntryId=team.entry_id">{{ team.name }}</button></div></div><div><span class="label">Visitante</span><div class="choices grid"><button v-for="team in teams()" :key="team.entry_id" type="button" class="choice" :aria-pressed="form.awayEntryId===team.entry_id" @click="form.awayEntryId=team.entry_id">{{ team.name }}</button></div></div></template>
        <template v-if="mode!=='teams'"><div class="form-grid"><div class="field"><label for="fixture-date">Día</label><input id="fixture-date" v-model="form.date" type="date" required></div><div class="field"><label for="fixture-time">Hora</label><input id="fixture-time" v-model="form.time" type="time" required></div></div><div><span class="label">Lugar</span><div class="choices grid"><button v-for="venue in venues" :key="venue.id" type="button" class="choice" :aria-pressed="form.venueId===venue.id" @click="form.venueId=venue.id">{{ venue.name }}</button></div><a v-if="!venues.length" :href="`#/torneo/${tournament.id}/ajustes`">Agregar lugar</a></div><div class="form-grid"><div class="field"><label for="fixture-court">Cancha dentro del lugar <span class="muted">(opcional)</span></label><input id="fixture-court" v-model="form.courtLabel" maxlength="80" placeholder="Solo si hay varias"></div><div class="field"><label for="fixture-duration">Duración (min)</label><input id="fixture-duration" v-model.number="form.durationMinutes" type="number" min="15" max="240" required></div></div></template>
        <button class="btn primary full" :disabled="busy||!form.homeEntryId||!form.awayEntryId||form.homeEntryId===form.awayEntryId||(mode!=='teams'&&!form.venueId)">Guardar</button>
      </form>
    </template>
    <div v-else class="empty-list">No se encontró la fecha.</div>
    <p v-if="error" class="notice amber" role="alert">{{ error }}</p><p v-if="message" class="notice neutral" role="status">{{ message }}</p>
  </div>
</template>
